```go
package main

import (
    "bytes"
    "fmt"
    "io"
)

func writeGreeting(destination io.Writer, name string) error {
    _, err := fmt.Fprintf(destination, "Hello, %s!", name)
    return err
}

func main() {
    var output bytes.Buffer
    _ = writeGreeting(&output, "Mina")
    label := fmt.Sprintf("bytes=%d", output.Len())
    fmt.Printf("%s %s\n", output.String(), label)
}
```
Fprintf writes into the caller's buffer, Sprintf builds a label, and only the final Printf targets standard output.

```go
package main

import "fmt"

type User struct {
    Name string
    Age  int
}

func main() {
    user := User{Name: "Mina", Age: 24}
    fmt.Printf("%v\n", user)
    fmt.Printf("%+v\n", user)
    fmt.Printf("%#v\n", user)
    fmt.Printf("%T %q %x\n", user, "go\n", 255)
}
```
Every verb matches its argument type, so go vet accepts the calls and the output contains no `%!` diagnostics.

```mermaid
flowchart TD
  A[fmt receives operand + verb] --> B{implements Formatter?}
  B -- Yes --> C[call Format]
  B -- No --> D{%#v and GoStringer?}
  D -- Yes --> E[call GoString]
  D -- No --> F{string-compatible verb and error/Stringer?}
  F -- Yes --> G[call Error or String]
  F -- No --> H[default formatting rules]
```

```go
package main

import "fmt"

type UserID string

func (id UserID) String() string {
    return fmt.Sprintf("user<%s>", string(id))
}

func main() {
    id := UserID("u-42")
    fmt.Printf("%s %v %T\n", id, id, id)
}
```
Converting `id` to plain string inside `String` prevents fmt from calling the same method again.
